const first=()=>(S.name||"Sofia").split(" ")[0];
const myLangs=()=>Object.keys(S.langs).length?Object.keys(S.langs):["ES","EN"];
const myLang=()=>myLangs()[0];
const native=p=>(p.langs.find(([c,l])=>l==="Native")||p.langs[0])[0];
const goodLangs=()=>{const g=Object.entries(S.langs).filter(([c,l])=>l!=="A2").map(([c])=>c);return g.length?g:myLangs()};
const speaks=p=>p.langs.find(([c,l])=>goodLangs().includes(c)&&(l==="Native"||l>="B2"));
const speaksSel=p=>{const s=S.f.langSel;return s?p.langs.find(([c,l])=>c===s&&(l==="Native"||l>="B2")):speaks(p)};
const ensure=()=>{S.q=S.q||"";S.f=S.f||{lang:true,verified:true,avail:"This week",max:60,sort:"Best match",area:""};if(S.f.area===undefined)S.f.area="";if(S.f.day===undefined)S.f.day="";if(S.f.time===undefined)S.f.time="";if(S.f.minR===undefined)S.f.minR=0;if(S.f.lic===undefined)S.f.lic=false;if(S.f.fast===undefined)S.f.fast=false;if(S.f.city===undefined)S.f.city="Tallinn";if(S.f.langSel===undefined)S.f.langSel="";if(S.f.pricing===undefined)S.f.pricing="";S.cat=S.cat||"";S.jobs2=S.jobs2||[];S.saved=S.saved||[];S.chats=S.chats||{};S.draft=S.draft||{}};
const find=id=>P.find(p=>p.id===id);
const money=n=>"€"+Number(n).toLocaleString("en-IE",{minimumFractionDigits:2,maximumFractionDigits:2});
const quote=j=>{const p=find(j.pid);const labour=p.pricing==="job"?p.jobPrice:j.hours*p.rate;const fee=Math.round((labour+j.materials)*0.1*100)/100;return{labour,fee,total:Math.round((labour+j.materials+fee)*100)/100}};
const STATUS={requested:["Quote requested","rev"],quoted:["Quote received","rev"],paid:["Paid, in escrow","ok"],disputed:["Problem reported","err"],done:["Completed","dark"],refunded:["Refunded","gray"],cancelled:["Cancelled","gray"]};
const pill=(st)=>{const [t,k]=STATUS[st];return `<span class="pill ${k}">${t}</span>`};
const stars=(r,n)=>`<span class="row" style="gap:4px;font-size:13px"><span>${[0,1,2,3,4].map(i=>`<span style="color:${i<Math.round(r)?"#F2C14E":"#D8D2C6"}">★</span>`).join("")}</span><b>${r.toFixed(1)}</b>${n?`<span class="muted">(${n})</span>`:""}</span>`;
const av=(p,s=52)=>`<span style="width:${s}px;height:${s}px;border-radius:50%;background:${p.bg};display:inline-flex;align-items:center;justify-content:center;font-family:Sora,sans-serif;font-weight:700;font-size:${Math.round(s*.36)}px;color:${p.bg==="#0E5A4C"||p.bg==="#D9643A"?"#fff":"#16201D"};flex-shrink:0">${p.ini}</span>`;
const lchip=([c,l])=>`<span class="lc ${myLangs().includes(c)?"on":""}"><b>${c}</b> <span>${l}</span></span>`;
const badge=b=>{const m={"Verified ID":["shield","#0E5A4C","#fff"],"Licensed":["check","#16201D","#BFE3D6"],"Top rated":["star","#16201D","#F2C14E"],"Escrow protected":["lock","#fff","#0E5A4C"]}[b];return `<span class="bd" style="background:${m[2]};color:${m[1]}">${ico(m[0],m[1],14)}${b}</span>`};
const why=p=>{const s=speaks(p);return s?`<b style="color:var(--green)">Speaks ${LNAME[s[0]]} ${s[1]}</b>`:`<b style="color:var(--green)">Translated chat</b>`};
const pcard=(p,compact)=>`<button class="pc" data-open="${p.id}"><span class="row" style="gap:12px;width:100%">${av(p)}<span style="flex:1;min-width:0;text-align:left"><span class="row" style="gap:6px"><b style="font-family:Sora,sans-serif;font-size:17px">${p.name}</b>${ico("shield","#0E5A4C",16)}</span><span class="muted" style="display:block;font-size:14px">${p.trade}  ·  ${p.area}</span>${stars(p.rating,p.reviews)}</span><span style="text-align:right;flex-shrink:0"><b style="font-family:Sora,sans-serif;font-size:18px;display:block">€${p.pricing==="job"?p.jobPrice:p.rate}</b><span class="muted" style="font-size:12px">${p.pricing==="job"?"per job":"per hour"}</span></span></span><span class="row wrap" style="gap:6px;width:100%">${p.langs.slice(0,3).map(lchip).join("")}</span>${compact?"":`<span class="row between" style="width:100%"><span class="muted">${why(p)}  ·  Replies in ~${p.reply}</span><span class="btn g sm" style="height:36px;padding:0 16px">View</span></span>`}</button>`;
const nav=a=>{const n=Object.values(S.chats).filter(c=>c.unread).length;return `<nav class="bnav">${[["ehome","search","Search"],["bookings","calendar","Bookings"],["chats","chat","Chats"],["me","user","Profile"]].map(([r,i,l])=>`<button data-nav="${r}" class="${a===r?"on":""}" aria-current="${a===r?"page":"false"}"><span class="pil">${ico(i,"#16201D",22)}${r==="chats"&&n?`<span class="nb">${n}</span>`:""}</span><span>${l}</span></button>`).join("")}</nav>`};
const topbar=()=>`<div class="row between" style="height:48px"><div class="row" style="gap:8px">${mark(28,"#F6F2EA")}<span style="font-family:Sora,sans-serif;font-weight:700;font-size:22px;letter-spacing:-.02em">kodu</span></div><button class="chip" style="height:40px" data-act="soon" aria-label="Change language">${ico("globe","#16201D",18)} ${myLang()}</button></div>`;
const sbar=(q,active)=>`<form data-form="search" class="in" style="border-radius:26px;height:52px">${ico("search","#56605C",20)}<input name="q" placeholder="Plumber, electrician, painter…" value="${esc(q)}" autocomplete="off"><button type="button" class="ib" data-go="filters" aria-label="Filters" style="width:36px;height:36px;margin-right:-8px;position:relative;background:var(--ivory);border:none">${ico("filter","#16201D",20)}${active?`<span class="nb" style="position:absolute;top:-4px;right:-4px">${active}</span>`:""}</button></form>`;
const hrow=inner=>`<div class="hwrap"><button class="harr prev" data-hs="prev" aria-label="Scroll back">${ico("back","#16201D",18)}</button><div class="hscroll">${inner}</div><button class="harr next" data-hs="next" aria-label="Scroll forward"><span style="display:inline-flex;transform:rotate(180deg)">${ico("back","#16201D",18)}</span></button></div>`;
const chatList=(list,active)=>`<div class="col clist" style="gap:0">${list.map(c=>{const p=find(c.pid);const lm=c.msgs[c.msgs.length-1];const last={when:lm.when||"",text:lm.text||(lm.quote?"Quote: "+money(quote(S.jobs2.find(x=>x.id===lm.quote)).total):"")};return `<button class="row citem ${active===p.id?"on":""}" data-chat="${p.id}">${av(p,48)}<span style="flex:1;min-width:0"><span class="row between"><b>${p.name}</b><span class="muted" style="font-size:12px">${last.when}</span></span><span class="muted" style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;${c.unread?"color:var(--ink);font-weight:700":""}">${esc(last.text)}</span></span>${c.unread?`<span class="nb">${c.unread}</span>`:""}</button>`}).join("")}</div>`;
const sh=(t,a,act)=>`<div class="row between" style="align-items:baseline"><span style="font-family:Sora,sans-serif;font-weight:700;font-size:19px;letter-spacing:-.02em">${t}</span>${a?`<button class="link" style="font-size:14px" ${act}>${a}</button>`:""}</div>`;

function results(){
  ensure();const f=S.f,q=S.q.toLowerCase();
  let r=P.filter(p=>!q||p.trade.toLowerCase().includes(q)||p.cat.toLowerCase().includes(q)||p.name.toLowerCase().includes(q)||p.tags.some(t=>t.toLowerCase().includes(q)));
  if(S.cat)r=r.filter(p=>p.cat===S.cat);
  if(f.area)r=r.filter(p=>p.area===f.area);
  if(f.verified)r=r.filter(p=>p.badges.includes("Verified ID"));
  r=r.filter(p=>p.city===f.city);
  if(f.lang)r=r.filter(p=>speaksSel(p));
  if(f.pricing)r=r.filter(p=>p.pricing===f.pricing);
  r=r.filter(p=>p.pricing==="job"||p.rate<=f.max);
  if(f.avail==="Today")r=r.filter(p=>p.slots.Tue);
  if(f.avail==="Weekends")r=r.filter(p=>p.slots.Sat||p.slots.Sun);
  const inWin=t=>{const h=+t.slice(0,2);return f.time===""||(f.time==="Morning"&&h<12)||(f.time==="Afternoon"&&h>=12&&h<16)||(f.time==="Evening"&&h>=16)};
  if(f.day||f.time)r=r.filter(p=>Object.entries(p.slots).some(([d,ss])=>(!f.day||d===f.day)&&ss.some(inWin)));
  if(f.minR)r=r.filter(p=>p.rating>=f.minR);
  if(f.lic)r=r.filter(p=>p.badges.includes("Licensed"));
  if(f.fast)r=r.filter(p=>p.reply.includes("min")&&parseInt(p.reply)<=30);
  const sort={"Best match":(a,b)=>(speaks(b)?1:0)-(speaks(a)?1:0)||b.rating-a.rating,"Highest rated":(a,b)=>b.rating-a.rating,"Lowest price":(a,b)=>a.rate-b.rate,"Nearest":(a,b)=>(a.area==="Kesklinn"?-1:1)-(b.area==="Kesklinn"?-1:1)}[f.sort];
  return r.sort(sort);
}
const activeFilters=()=>{ensure();const f=S.f;return (f.lang?1:0)+(f.verified?1:0)+(f.avail!=="This week"?1:0)+(f.max<60?1:0)+(f.area?1:0)+(f.day?1:0)+(f.time?1:0)+(f.minR?1:0)+(f.lic?1:0)+(f.fast?1:0)+(f.city!=="Tallinn"?1:0)+(f.pricing?1:0)};

Object.assign(SCREENS,{
ehome:()=>{ensure();const open=S.jobs2.find(j=>j.status!=="done"&&j.status!=="cancelled");const inCity=P.filter(p=>p.city===S.f.city);const near=inCity.filter(speaks).slice(0,3);const popular=[...inCity].sort((a,b)=>b.reviews-a.reviews).slice(0,8);const recent=(S.recent||[]).map(find).filter(Boolean).slice(0,6);const langsHere=new Set(inCity.flatMap(p=>p.langs.map(l=>l[0]))).size;const dist=(S.address||"Kesklinn").split(",")[1]||"Kesklinn";
 const mini=p=>`<button class="mini" data-open="${p.id}">${av(p,44)}<b>${p.name.split(" ")[0]}</b><span class="muted" style="font-size:12px">${p.trade}</span><span class="row" style="gap:4px;font-size:12px"><span style="color:#F2C14E">★</span><b>${p.rating.toFixed(1)}</b><span class="muted">·</span><span>€${p.pricing==="job"?p.jobPrice:p.rate}${p.pricing==="job"?"":"/h"}</span></span></button>`;
 return `${topbar()}<div class="col" style="gap:4px"><h2>${({ES:"Hola",EN:"Hello",ET:"Tere",RU:"Привет",UK:"Привіт",DE:"Hallo",FI:"Hei",PT:"Olá",FR:"Salut",IT:"Ciao"})[myLang()]||"Hello"} ${esc(first())}</h2><p class="sub row" style="gap:6px">${ico("pin","#56605C",16)}${esc(dist.trim())}, ${S.f.city}  ·  ${inCity.length} verified providers</p></div>
${sbar("",activeFilters())}
<div class="grid3" style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">${CATS.map(([c,i,bg])=>`<button class="cat" style="background:${bg}" data-cat="${c}">${ico(i,"#16201D",24)}<b>${c}</b></button>`).join("")}</div>
${open?`<button class="jobcard" data-job="${open.id}"><span class="row between"><span style="font-size:13px;font-weight:700;color:var(--mint)">Open job</span>${pill(open.status)}</span><b style="font-family:Sora,sans-serif;font-size:18px;display:block;margin-top:6px">${esc(open.title)}</b><span style="font-size:13px;color:rgba(255,255,255,.7)">${find(open.pid).name}  ·  ${open.day} ${open.slot}${open.status!=="requested"?"  ·  "+money(quote(open).total):""}</span></button>`:
 `<button class="hero" data-cat="Electrical"><span style="flex:1;text-align:left"><span style="font-size:12px;font-weight:700;color:var(--terra);letter-spacing:.04em">NEW TENANT?</span><b style="font-family:Sora,sans-serif;font-size:18px;display:block;line-height:1.2;margin:4px 0 6px">Book a safety check before the landlord inspection</b><span class="muted" style="font-size:13px">Certified electricians from €45, report in your language</span></span><span class="eic" style="width:64px;height:64px;border-radius:20px;background:var(--mint)">${ico("shield","#0E5A4C",30)}</span></button>`}
${sh(`Popular in ${S.f.city}`,"See all",'data-act="seeall"')}${hrow(popular.map(mini).join(""))}
<div class="row" style="gap:10px">${[["shield","Verified ID","Every provider checked"],["lock","Escrow","Pay when it is done"],["globe",langsHere+" languages","Chat translates the rest"]].map(([i,t,s])=>`<div class="card" style="flex:1;padding:12px;display:flex;flex-direction:column;gap:6px;align-items:flex-start"><span class="eic" style="width:34px;height:34px;border-radius:10px">${ico(i,"#16201D",18)}</span><b style="font-size:13px;line-height:1.2">${t}</b><span class="muted" style="font-size:11px;line-height:1.3">${s}</span></div>`).join("")}</div>
${sh(`Speak ${myLangs().slice(0,2).map(c=>LNAME[c]).join(" or ")} near you`,"See all",'data-act="seeall"')}<div class="col grid2" style="gap:12px">${near.length?near.map(p=>pcard(p,true)).join(""):`<p class="muted">No providers speak ${LNAME[myLang()]} yet. Everyone else is one translated chat away.</p>`}</div>
${recent.length?`${sh("Recently viewed","")}${hrow(recent.map(mini).join(""))}`:""}
<div class="card" style="background:var(--mint);border:none;display:flex;gap:12px;align-items:center"><span class="eic" style="width:48px;height:48px;background:#fff;border-radius:14px">${ico("star","#16201D",22)}</span><span style="flex:1"><b style="font-size:15px;display:block">Know a good tradesperson?</b><span class="muted" style="font-size:13px">Invite them to Kodu and get €10 off your next job.</span></span><button class="btn s sm" style="height:40px;border-color:var(--ink)" data-act="soon">Invite</button></div>
<div style="height:12px"></div>${nav("ehome")}`},

search:()=>{ensure();const r=results();return `<div class="row" style="gap:10px"><button class="ib" data-go="back" aria-label="Back">${ico("back")}</button><div style="flex:1">${sbar(S.q||S.cat,activeFilters())}</div></div>
<div class="row" style="gap:8px;overflow-x:auto;margin:0 -20px;padding:0 20px"><button class="chip ${!S.cat?"on":""}" data-cat="">All</button>${CATS.map(([c])=>`<button class="chip ${S.cat===c?"on":""}" data-cat="${c}">${c}</button>`).join("")}</div>
<div class="row" style="gap:8px;overflow-x:auto;margin:0 -20px;padding:0 20px"><button class="chip on" data-go="filters">${ico("pin","#fff",16)}${S.f.city}</button>${S.f.area?`<button class="chip on" data-fv="area" data-val="">${S.f.area} ×</button>`:""}${S.f.day?`<button class="chip on" data-fv="day" data-val="">${ico("calendar","#fff",16)}${S.f.day}${S.f.time?" "+S.f.time.toLowerCase():""} ×</button>`:S.f.time?`<button class="chip on" data-fv="time" data-val="">${S.f.time} ×</button>`:""}${S.f.minR?`<button class="chip on" data-fv="minR" data-val="0">${S.f.minR}+ ×</button>`:""}${[["lang","Speaks "+(S.f.langSel||myLangs().slice(0,2).join(" or ")),"globe"],["verified","Verified","shield"]].map(([k,l,i])=>`<button class="chip ${S.f[k]?"on":""}" data-f="${k}">${ico(i,S.f[k]?"#fff":"#16201D",16)}${l}</button>`).join("")}${["Today","This week","Weekends"].map(a=>`<button class="chip ${S.f.avail===a?"on":""}" data-fv="avail" data-val="${a}">${a}</button>`).join("")}</div>
<div class="row between"><span class="muted"><b style="color:var(--ink)">${r.length} ${r.length===1?"provider":"providers"}</b> in ${S.f.area?S.f.area+", ":""}${S.f.city}</span><span class="muted">${S.f.sort}</span></div>
<div class="col grid2" style="gap:12px">${r.length?r.map(p=>pcard(p)).join(""):`<div class="empty"><span class="eic">${ico("search","#16201D",30)}</span><b style="font-family:Sora,sans-serif;font-size:18px">No ${LNAME[myLang()]} speaking ${S.cat||S.q||"providers"} with these filters</b><p class="muted">Everyone on Kodu can chat with you through translation.</p><button class="btn s sm" data-f="lang">Include translated chat</button></div>`}</div>
<div style="height:12px"></div>${nav("ehome")}`},

filters:()=>{ensure();const f=S.f;return `<div class="sheetbg" data-go="back"></div><div class="sheet"><div class="grab"></div><div class="row between"><h2 style="font-size:20px">Filters</h2><button class="ib" data-go="back" aria-label="Close filters" style="width:36px;height:36px;font-size:22px;line-height:1">×</button></div>
<div class="col"><span class="muted" style="font-weight:700">City</span><div class="row wrap">${Object.keys(CITIES).map(c=>`<button class="chip ${f.city===c?"on":""}" data-city="${c}">${c}</button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">District in ${f.city}</span><div class="row wrap"><button class="chip ${!f.area?"on":""}" data-fv="area" data-val="">Anywhere</button>${CITIES[f.city].map(a=>`<button class="chip ${f.area===a?"on":""}" data-fv="area" data-val="${a}">${a}</button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">Language</span><div class="row wrap"><button class="chip ${!f.lang?"on":""}" data-langsel="any">Any, translate chat</button><button class="chip ${f.lang&&!f.langSel?"on":""}" data-langsel="">My languages</button>${ALL_LANGS.map(([c,n])=>`<button class="chip ${f.lang&&f.langSel===c?"on":""}" data-langsel="${c}">${n}</button>`).join("")}</div><p class="muted">Matches providers who speak it at B2 or better. Everyone else is reachable through translated chat.</p></div>
<div class="col"><span class="muted" style="font-weight:700">Pricing</span><div class="row wrap">${[["","Any"],["hour","Hourly rate"],["job","Fixed price per job"]].map(([v,l])=>`<button class="chip ${f.pricing===v?"on":""}" data-fv="pricing" data-val="${v}">${l}</button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">Category</span><div class="row wrap"><button class="chip ${!S.cat?"on":""}" data-catf="">All</button>${CATS.map(([c])=>`<button class="chip ${S.cat===c?"on":""}" data-catf="${c}">${c}</button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">Trust</span><label class="chk"><input type="checkbox" data-f="verified" ${f.verified?"checked":""}><span class="box">${ico("check","#fff",16)}</span><span>Verified ID only</span></label><label class="chk"><input type="checkbox" data-f="lic" ${f.lic?"checked":""}><span class="box">${ico("check","#fff",16)}</span><span>Licensed only (plumbing and electrical)</span></label><label class="chk"><input type="checkbox" data-f="fast" ${f.fast?"checked":""}><span class="box">${ico("check","#fff",16)}</span><span>Replies within 30 minutes</span></label></div>
<div class="col"><span class="muted" style="font-weight:700">Availability</span><div class="row wrap">${["Today","This week","Weekends"].map(a=>`<button class="chip ${f.avail===a?"on":""}" data-fv="avail" data-val="${a}">${a}</button>`).join("")}</div></div>
<div class="col"><div class="row between"><span class="muted" style="font-weight:700">Date</span>${f.day?`<button class="link" style="font-size:13px" data-fv="day" data-val="">Any day</button>`:`<span class="muted">Any day</span>`}</div><div class="row" style="gap:6px">${DAYS.map(([d,n])=>`<button class="day ${f.day===d?"sel":""}" data-fv="day" data-val="${f.day===d?"":d}"><small>${d}</small><b>${n}</b></button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">Time of day</span><div class="row wrap">${[["","Any time"],["Morning","Morning, before 12"],["Afternoon","Afternoon, 12 to 16"],["Evening","Evening, after 16"]].map(([v,l])=>`<button class="chip ${f.time===v?"on":""}" data-fv="time" data-val="${v}">${l}</button>`).join("")}</div>${f.day||f.time?`<p class="muted">Showing providers with a free slot ${f.day?"on "+f.day:""} ${f.time?"in the "+f.time.toLowerCase():""}. Pick the exact slot on their profile.</p>`:""}</div>
<div class="col"><span class="muted" style="font-weight:700">Minimum rating</span><div class="row wrap">${[[0,"Any"],[4.5,"4.5 and up"],[4.8,"4.8 and up"],[5,"5.0 only"]].map(([v,l])=>`<button class="chip ${f.minR===v?"on":""}" data-fvn="minR" data-val="${v}">${l}</button>`).join("")}</div></div>
<div class="col" style="${f.pricing==="job"?"display:none":""}"><div class="row between"><span class="muted" style="font-weight:700">Hourly rate</span><b style="font-size:13px">up to €${f.max}</b></div><input type="range" min="20" max="60" step="5" value="${f.max}" data-range="max" aria-label="Maximum hourly rate"><div class="row between muted" style="font-size:12px"><span>€20</span><span>€60</span></div></div>
<div class="col"><span class="muted" style="font-weight:700">Sort by</span>${["Best match","Highest rated","Lowest price","Nearest"].map(o=>`<button class="row" style="gap:10px;background:none;border:none;padding:6px 0;font:inherit;font-size:15px" data-fv="sort" data-val="${o}"><span class="radio ${f.sort===o?"on":""}"></span>${o}${o==="Best match"?" for my languages":""}</button>`).join("")}</div>
<div class="row" style="gap:10px;margin-top:4px"><button class="btn s" style="width:120px;height:52px" data-act="resetF">Reset</button><button class="btn p" style="height:52px;font-size:15px" data-go="back">Show ${results().length} providers</button></div></div>`},

profile:()=>{const p=find(S.view);const saved=S.saved.includes(p.id);return `<div class="row between" style="height:44px"><button class="ib" data-go="back" aria-label="Back">${ico("back")}</button><div class="row" style="gap:8px"><button class="ib" data-report="profile" aria-label="Report this profile">${ico("flag","#16201D",18)}</button><button class="ib" data-act="share" aria-label="Share">${ico("send","#16201D",20)}</button><button class="ib" data-save="${p.id}" aria-label="${saved?"Remove from saved":"Save"}" aria-pressed="${saved}" style="${saved?"background:var(--mint);border-color:var(--mint)":""}">${ico("star","#16201D",20)}</button></div></div>
<div class="col center" style="align-items:center;gap:10px">${av(p,88)}<div><div class="row" style="justify-content:center;gap:6px"><span style="font-family:Sora,sans-serif;font-weight:700;font-size:24px;letter-spacing:-.02em">${p.name}</span>${ico("shield","#0E5A4C",20)}</div><div class="sub" style="color:var(--muted)">${p.trade}  ·  ${p.area}, Tallinn</div></div><div class="row wrap" style="justify-content:center;gap:6px">${p.badges.map(badge).join("")}</div></div>
<div class="card row" style="padding:0">${[[p.rating.toFixed(1),p.reviews+" reviews"],[p.rel+"%","on time"],[p.reply,"reply time"],[p.pricing==="job"?"€"+p.jobPrice:"€"+p.rate,p.pricing==="job"?"per job":"per hour"]].map(([v,l],i)=>`<span class="stat" style="${i?"border-left:1px solid #EDE8DF":""}"><b>${v}</b><small>${l}</small></span>`).join("")}</div>
<div class="col"><div class="row between" style="align-items:baseline"><b style="font-family:Sora,sans-serif;font-size:17px">Languages</b><span class="muted">Chat translates to ${LNAME[myLang()]}</span></div><div class="row wrap" style="gap:6px">${p.langs.map(lchip).join("")}</div><div class="note">${ico("globe","#16201D",16)}<span>${speaks(p)?`${p.name.split(" ")[0]} speaks ${LNAME[speaks(p)[0]]} at ${speaks(p)[1]}. You can write in ${LNAME[myLang()]} and Kodu translates both ways.`:`${p.name.split(" ")[0]} does not speak ${LNAME[myLang()]}. Kodu translates every message both ways, and shows the original under each one.`}</span></div></div>
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">About</b><p class="sub">${p.bio}</p><div class="row wrap" style="gap:6px">${p.tags.map(t=>`<span class="chip">${t}</span>`).join("")}</div></div>
<div class="col" style="gap:10px"><div class="row between" style="align-items:baseline"><b style="font-family:Sora,sans-serif;font-size:17px">Reviews from expats</b><span class="muted">${p.reviews} total</span></div>${p.revs.map(([n,l,t,r,w])=>`<div class="card col" style="gap:8px;padding:14px"><div class="row" style="gap:10px"><span style="width:36px;height:36px;border-radius:18px;background:var(--mint);display:inline-flex;align-items:center;justify-content:center;font-weight:700">${n[0]}</span><span style="flex:1"><b style="font-size:15px">${n}</b> <span class="muted">· expat, ${l}</span><span class="muted" style="display:block;font-size:12px">${w}</span></span>${stars(r)}</div><p class="sub" style="font-size:14px">${t}</p></div>`).join("")}</div>
<div class="col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Next available</b><div class="row" style="gap:6px">${DAYS.map(([d,n])=>`<span class="day ${p.slots[d]?"":"off"}"><small>${d}</small><b>${n}</b></span>`).join("")}</div><div class="row wrap" style="gap:8px">${Object.entries(p.slots).slice(0,2).flatMap(([d,ss])=>ss.map(s=>`<button class="slot" data-book="${p.id}" data-day="${d}" data-slot="${s}">${d} ${s}</button>`)).join("")}</div></div>
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">Why you can trust ${p.name.split(" ")[0]}</b><div class="card" style="padding:4px 14px">${[["shield","Identity checked","Document verified by our partner"],["check",p.badges.includes("Licensed")?"Licence on file":"Trade experience declared","Shown on request"],["lock","Escrow on every job","Pay only when you confirm the work"]].map(([i,t,s])=>`<div class="row" style="gap:12px;padding:10px 0;border-bottom:1px solid #EDE8DF"><span class="eic" style="width:36px;height:36px;border-radius:11px">${ico(i,"#16201D",18)}</span><span><b style="font-size:15px">${t}</b><span class="muted" style="display:block">${s}</span></span></div>`).join("")}</div></div>

<div style="height:12px"></div><div class="cta"><span style="width:78px"><b style="font-family:Sora,sans-serif;font-size:20px">€${p.pricing==="job"?p.jobPrice:p.rate}<span class="muted" style="font-size:13px;font-weight:500">${p.pricing==="job"?" per job":"/h"}</span></b><span class="muted" style="display:block;font-size:12px">quote before work</span></span><button class="btn g" style="width:100px;height:52px;font-size:15px" data-chat="${p.id}">Message</button><button class="btn p" style="flex:1;height:52px;font-size:15px;white-space:nowrap" data-book="${p.id}">Request quote</button></div>`},

book:()=>{const p=find(S.view);const d=S.draft;return `${bar(1,3)}${head("Describe the job",`${p.name.split(" ")[0]} replies with a written quote before any work starts.`)}
<form data-form="book" class="col" style="gap:14px">
<label class="f"><span class="l">What needs doing</span><div class="in ${err.title?"err":""}"><input name="title" placeholder="Leaking kitchen tap" value="${esc(d.title||"")}"></div>${err.title?`<span class="errt">${err.title}</span>`:""}</label>
<label class="f"><span class="l">Details</span><textarea name="desc" class="ta" placeholder="When it started, where it is, anything you have tried. Write in ${LNAME[myLang()]}, ${p.name.split(" ")[0]} reads it in ${LNAME[native(p)]}.">${esc(d.desc||"")}</textarea></label>
<div class="col"><span class="muted" style="font-weight:700">Photos</span><div class="row">${["Photo 1","Photo 2"].map(k=>`<button type="button" class="photo ${d[k]?"done":""}" data-dphoto="${k}">${d[k]?ico("check","#fff",22):ico("plus","#56605C",20)}${d[k]?"Added":"Add photo"}</button>`).join("")}</div></div>
<div class="col"><span class="muted" style="font-weight:700">Urgency</span>${chips("urgency",["Flexible","This week","Urgent"],S.urgency||"This week")}</div>
${S.landlord&&S.llName?`<div class="note">${ico("shield","#16201D",16)}<span>The quote is also sent to ${esc(S.llName)} for approval, since your landlord arranges repairs.</span></div>`:""}
<div class="note">${ico("pin","#16201D",16)}<span>${p.name.split(" ")[0]} sees your district (${((S.address||"Kesklinn").split(",")[1]||"Kesklinn").trim()}) now and the full address once you pay.</span></div>
<div class="foot"><button class="btn p" type="submit">Choose a time</button></div></form>`},

slots:()=>{const p=find(S.view);const d=S.draft;const day=d.day||Object.keys(p.slots)[0];return `${bar(2,3)}${head("Pick a time",`${p.name.split(" ")[0]}'s free slots this week. Jobs usually take one to two hours.`)}
<div class="row" style="gap:6px">${DAYS.map(([dd,n])=>`<button class="day ${p.slots[dd]?"":"off"} ${day===dd?"sel":""}" data-day="${dd}" ${p.slots[dd]?"":"disabled"}><small>${dd}</small><b>${n}</b></button>`).join("")}</div>
<div class="row wrap" style="gap:8px">${(p.slots[day]||[]).map(s=>`<button class="slot ${d.day===day&&d.slot===s?"sel":""}" data-pick="${s}">${s}</button>`).join("")}</div>
${err.slot?`<span class="errt">${err.slot}</span>`:""}
<div class="card col" style="gap:4px"><span class="muted" style="font-weight:700">Estimate</span><div class="row between"><span>${p.pricing==="job"?"Fixed price per job":"1.5 h × €"+p.rate}</span><b>€${(p.pricing==="job"?p.jobPrice:1.5*p.rate).toFixed(2)}</b></div><p class="muted">Final price comes in ${p.name.split(" ")[0]}'s quote. Materials and the 10% Kodu fee are shown before you pay.</p></div>
<div class="foot"><button class="btn p" data-act="sendRequest">Send request</button></div>`},

job:()=>{const j=S.jobs2.find(x=>x.id===S.jobId);const p=find(j.pid);const q=quote(j);return `${bar()}<div class="row between"><h2>${esc(j.title)}</h2>${pill(j.status)}</div>
<div class="card row" style="gap:12px">${av(p,44)}<span style="flex:1"><b>${p.name}</b><span class="muted" style="display:block">${p.trade}  ·  ${j.day} ${j.slot}</span></span><button class="btn g sm" style="height:40px" data-chat="${p.id}">Chat</button></div>
${j.status==="requested"?`<div class="note">${ico("globe","#16201D",16)}<span>Request sent and translated to ${LNAME[native(p)]}. ${p.name.split(" ")[0]} usually replies in ~${p.reply}. Prototype: open the chat to receive the quote.</span></div>`:""}
${j.status!=="requested"?`<div class="card col" style="gap:0;padding:6px 16px">${[[p.pricing==="job"?"Fixed price for the job":"Labour  "+j.hours+" h × €"+p.rate,money(q.labour)],["Materials  "+j.matDesc,money(j.materials)],["Kodu service fee 10%",money(q.fee)]].map(([a,b])=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid #EDE8DF;font-size:15px"><span>${a}</span><b style="font-family:Sora,sans-serif">${b}</b></div>`).join("")}<div class="row between" style="padding:12px 0;font-size:17px;color:var(--green)"><b>${j.status==="paid"||j.status==="done"?"Held in escrow":"Total to hold in escrow"}</b><b style="font-family:Sora,sans-serif">${money(q.total)}</b></div></div>`:""}
${j.status==="paid"?`<div class="note">${ico("lock","#16201D",16)}<span>Paid ${j.paidAt}. Released to ${p.name.split(" ")[0]} when you confirm the job is done, or automatically 72 h after the visit.</span></div>`:""}
${j.status==="done"?`<div class="note">${ico("check","#16201D",16)}<span>Completed. ${money(q.total-(j.refund||0))} released to ${p.name.split(" ")[0]}${j.refund?" after the partial refund":""}. Receipt KD 2026 ${j.id.slice(-4)} is in your email.</span></div>`:""}
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">Details</b><p class="sub">${esc(j.desc||"No extra details.")}</p><div class="row wrap"><span class="chip">${j.urgency}</span>${j.photos?`<span class="chip">${j.photos} photos</span>`:""}</div></div>
${j.status==="quoted"&&j.ll?`<div class="note" style="${j.ll==="pending"?"background:#FBEFD0":""}">${ico("shield","#16201D",16)}<span>${j.ll==="pending"?`Quote sent to ${esc(S.llName)} for approval. You can pay once they approve.`:`Approved by ${esc(S.llName)}. You can pay now.`}</span></div>`:""}
${j.status==="disputed"?`<div class="note" style="background:#F9DED3">${ico("lock","#16201D",16)}<span><b>Payment on hold.</b> ${p.name.split(" ")[0]} has 48 h to respond, then Kodu proposes a resolution. Reason: ${esc(j.dispute||"")}.</span></div><div class="card col" style="gap:8px"><span class="muted" style="font-weight:700">Prototype: resolve the dispute</span><div class="row" style="gap:8px"><button class="btn g sm" style="flex:1;padding:0 8px;font-size:14px" data-resolve="partial">Refund half</button><button class="btn g sm" style="flex:1;padding:0 8px;font-size:14px" data-resolve="full">Refund all</button><button class="btn g sm" style="flex:1;padding:0 8px;font-size:14px" data-resolve="release">Release</button></div></div>`:""}
${j.refund?`<div class="note">${ico("check","#16201D",16)}<span>${money(j.refund)} refunded to your card. It arrives within 5 working days.</span></div>`:""}
<div class="foot">${j.status==="quoted"?`<button class="btn a" data-go="pay" ${j.ll==="pending"?"disabled":""}>${ico("lock","#fff",20)}Pay ${money(q.total)} securely</button><button class="btn s" data-act="declineQuote">Decline quote</button>`:j.status==="paid"?`<button class="btn p" data-act="confirmDone">Confirm job is done</button><div class="row" style="gap:10px"><button class="btn s" style="flex:1" data-go="dispute">Report a problem</button><button class="btn s" style="flex:1" data-act="cancel">Cancel booking</button></div>`:j.status==="done"?(j.rated?`<button class="btn p" data-rebook="${p.id}">Book ${p.name.split(" ")[0]} again</button><p class="center muted">Thanks for your review.</p>`:`<button class="btn p" data-go="rate">Rate ${p.name.split(" ")[0]}</button><button class="btn s" data-rebook="${p.id}">Book again</button>`):j.status==="refunded"?`<button class="btn s" data-cat="${p.cat}">Find another ${p.trade.toLowerCase()}</button>`:j.status==="requested"?`<button class="btn s" data-act="cancel">Cancel request</button>`:""}</div>`},

dispute:()=>{const j=S.jobs2.find(x=>x.id===S.jobId);const p=find(j.pid);S.dsp=S.dsp||{};return `${bar()}${head("Report a problem","Your payment stays on hold while Kodu looks into it. "+p.name.split(" ")[0]+" is notified and can reply.")}
<div class="col"><span class="muted" style="font-weight:700">What went wrong?</span><div class="row wrap">${["Did not show up","Job not finished","Poor quality","Charged more than the quote","Damage to my home","Something else"].map(r=>`<button class="chip ${S.dsp.r===r?"on":""}" data-dr="${r}">${r}</button>`).join("")}</div></div>
<label class="f"><span class="l">Tell us more</span><textarea class="ta" name="dtext" placeholder="Write in ${LNAME[myLang()]}. ${p.name.split(" ")[0]} reads it translated.">${esc(S.dsp.t||"")}</textarea></label>
<div class="col"><span class="muted" style="font-weight:700">Photos</span><div class="row">${["P1","P2"].map(k=>`<button type="button" class="photo ${S.dsp[k]?"done":""}" data-dp="${k}">${S.dsp[k]?ico("check","#fff",22):ico("plus","#56605C",20)}${S.dsp[k]?"Added":"Add photo"}</button>`).join("")}</div></div>
${err.dr?`<span class="errt">${err.dr}</span>`:""}
<div class="note">${ico("shield","#16201D",16)}<span>This does not affect your legal rights against the provider for faulty work.</span></div>
<div class="foot"><button class="btn a" data-act="sendDispute">Report and hold payment</button></div>`},

saved:()=>{ensure();const list=S.saved.map(find).filter(Boolean);return `${bar()}${head("Saved providers",list.length?"Book the people you trust again in two taps.":"Tap the star on any profile to save it here.")}<div class="col grid2" style="gap:12px">${list.map(p=>pcard(p)).join("")}</div>${list.length?"":`<button class="btn s" data-nav="ehome">Find a service</button>`}`},

report:()=>{const t=S.reportTarget||{};S.rp=S.rp||"";return `${bar()}${head("Report "+esc(t.name||"this content"),"Reports are reviewed by a person. We tell you what we decided and why.")}
<div class="col">${["Fake profile or impersonation","Offensive or discriminatory content","Asked to pay outside Kodu","Unsafe behaviour","Spam or scam","Something else"].map(r=>`<button class="row" style="gap:10px;background:none;border:none;padding:8px 0;font:inherit;font-size:15px;text-align:left" data-rp="${r}"><span class="radio ${S.rp===r?"on":""}"></span>${r}</button>`).join("")}</div>
<label class="f"><span class="l">Details (optional)</span><textarea class="ta" name="rptext"></textarea></label>
<div class="foot"><button class="btn p" data-act="sendReport" ${S.rp?"":"disabled"}>Send report</button></div>`},

pay:()=>{const j=S.jobs2.find(x=>x.id===S.jobId);const p=find(j.pid);const q=quote(j);S.payMethod=S.payMethod||"Visa";return `${bar()}${head("Pay securely","Money is held by Kodu, not sent to the provider, until you confirm the job.")}
<div class="card col" style="gap:0;padding:6px 16px">${[["Labour",money(q.labour)],["Materials",money(j.materials)],["Kodu service fee",money(q.fee)]].map(([a,b])=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid #EDE8DF;font-size:15px"><span>${a}</span><b style="font-family:Sora,sans-serif">${b}</b></div>`).join("")}<div class="row between" style="padding:12px 0;font-size:17px;color:var(--green)"><b>Total held in escrow</b><b style="font-family:Sora,sans-serif">${money(q.total)}</b></div></div>
<div class="col">${[["Visa","Ending 4421","VISA"],["Apple Pay",first()+"'s iPhone","APPL"],["Revolut","Ending 0912","REV"]].map(([t,s,g])=>`<button class="pm ${S.payMethod===t?"on":""}" data-pay="${t}"><span class="tag">${g}</span><span style="flex:1"><b>${t}</b><small>${s}</small></span><span class="radio ${S.payMethod===t?"on":""}"></span></button>`).join("")}</div>
<div class="note">${ico("lock","#16201D",16)}<span><b>Held in escrow.</b> Released to ${p.name.split(" ")[0]} when you confirm, or automatically 72 h after the visit. Cancelling within 24 h of the slot costs €15.</span></div>
<p class="muted" style="line-height:1.45">By paying you agree to the booking terms. Payments are processed by Stripe; Kodu never stores your card number.</p>
<div class="foot"><button class="btn a" data-act="payNow">${ico("lock","#fff",20)}Pay ${money(q.total)} with ${S.payMethod}</button></div>`},

paid:()=>{const j=S.jobs2.find(x=>x.id===S.jobId);const p=find(j.pid);return `<div class="col center" style="margin:auto;width:100%;align-items:center;gap:14px"><span class="eic" style="width:120px;height:120px;border-radius:60px">${ico("check","#0E5A4C",56)}</span><h2>Booked for ${j.day} ${j.slot}</h2><p class="sub">${money(quote(j).total)} is held safely. ${p.name.split(" ")[0]} has your full address now and will message you in ${LNAME[myLang()]}.</p>
<div class="card col" style="text-align:left;width:100%;gap:8px">${[["Confirmation","Sent to "+esc(S.email||"your email")],["Address shared","Yes, after payment only"],["Cancel for free","Until "+j.day+" "+j.slot+", minus 24 h"]].map(([a,b])=>`<div class="row between" style="font-size:14px"><span class="muted">${a}</span><b style="text-align:right">${b}</b></div>`).join("")}</div></div>
<div class="foot"><button class="btn p" data-chat="${p.id}">Open chat with ${p.name.split(" ")[0]}</button><button class="btn s" data-nav="bookings">See my bookings</button></div>`},

rate:()=>{const j=S.jobs2.find(x=>x.id===S.jobId);const p=find(j.pid);S.rv=S.rv||{stars:0,tags:[]};return `${bar()}<div class="col center" style="align-items:center;gap:12px">${av(p,72)}<h2>How was ${p.name.split(" ")[0]}?</h2><p class="sub">Only expats can review, and reviews are shown with your language.</p>
<div class="row" style="gap:8px">${[1,2,3,4,5].map(i=>`<button class="starb ${i<=S.rv.stars?"on":""}" data-star="${i}" aria-label="${i} stars">★</button>`).join("")}</div>
<div class="row wrap" style="justify-content:center;gap:6px">${["On time","Clear price","Spoke my language","Tidy","Would book again"].map(t=>`<button class="chip ${S.rv.tags.includes(t)?"on":""}" data-rtag="${t}">${t}</button>`).join("")}</div></div>
<label class="f"><span class="l">A few words (optional)</span><textarea class="ta" name="rvtext" placeholder="Write in ${LNAME[myLang()]}">${esc(S.rv.text||"")}</textarea></label>
<div class="foot"><button class="btn p" data-act="sendReview">Send review</button></div>`},

bookings:()=>{ensure();const list=[...S.jobs2].reverse();return `${topbar()}<h2>Bookings</h2>${list.length?`<div class="col grid2" style="gap:12px">${list.map(j=>{const p=find(j.pid);return `<button class="pc" data-job="${j.id}" style="gap:8px"><span class="row between" style="width:100%"><b style="font-family:Sora,sans-serif;font-size:17px">${esc(j.title)}</b>${pill(j.status)}</span><span class="row" style="gap:10px;width:100%">${av(p,36)}<span class="muted" style="text-align:left">${p.name}  ·  ${j.day} ${j.slot}${j.status!=="requested"?"<br>"+money(quote(j).total):""}</span></span></button>`}).join("")}</div>`:`<div class="empty"><span class="eic">${ico("calendar","#16201D",30)}</span><b style="font-family:Sora,sans-serif;font-size:18px">No bookings yet</b><p class="muted">Request a quote from any provider and it shows up here.</p><button class="btn s sm" data-nav="ehome">Find a service</button></div>`}
<div style="height:12px"></div>${nav("bookings")}`},

chats:()=>{ensure();const list=Object.values(S.chats).sort((a,b)=>b.t-a.t);return `${topbar()}<h2>Chats</h2>${list.length?chatList(list):`<div class="empty"><span class="eic">${ico("chat","#16201D",30)}</span><b style="font-family:Sora,sans-serif;font-size:18px">No chats yet</b><p class="muted">Message any provider from their profile. Every chat is translated both ways.</p></div>`}
<div style="height:12px"></div>${nav("chats")}`},

chat:()=>{ensure();const p=find(S.view);const c=S.chats[p.id];c.unread=0;const pl=native(p);const list=Object.values(S.chats).sort((a,b)=>b.t-a.t);
 const msgs=c.msgs.map(m=>m.sys?`<div class="muted center" style="font-size:12px;padding:4px 0">${m.text}</div>`:m.quote?(()=>{const j=S.jobs2.find(x=>x.id===m.quote);const q=quote(j);return `<div class="row"><div class="qcard"><div class="row between"><span style="font-size:13px;font-weight:700;color:var(--green)">Quote from ${p.name.split(" ")[0]}</span>${pill(j.status)}</div><b style="font-family:Sora,sans-serif;font-size:22px">${money(q.total)}</b><span class="muted">${p.pricing==="job"?"fixed price":j.hours+" h labour"}, ${j.matDesc}, ${j.day} ${j.slot}</span>${j.status==="quoted"?`<div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" data-job="${j.id}">View and pay</button><button class="btn s sm" style="flex:1" data-act="declineQuote" data-jid="${j.id}">Decline</button></div>`:""}</div></div>`})():`<div class="row" style="justify-content:${m.me?"flex-end":"flex-start"}"><div class="bub2 ${m.me?"me":""}"><span>${esc(m.text)}</span>${S.showOrig===false?"":`<span class="orig">${ico("globe",m.me?"rgba(255,255,255,.7)":"#56605C",12)} ${m.me?`Delivered in ${LNAME[pl]}`:`${pl}: ${esc(m.orig)}`}</span>`}</div></div>`).join("")+(c.typing?`<div class="row"><div class="bub2" style="padding:12px 16px"><span class="dots"><i></i><i></i><i></i></span></div></div>`:"");
 return `<div class="chatpage"><aside class="chatside dk"><h2 style="font-size:22px;margin-bottom:8px">Chats</h2>${chatList(list,p.id)}</aside><div class="chatmain">
<div class="row chathead" style="gap:10px;height:48px"><button class="ib nodk" data-go="back" aria-label="Back">${ico("back")}</button>${av(p,40)}<span style="flex:1"><b style="display:block">${p.name}</b><span class="muted" style="font-size:12px">${p.trade}  ·  replies in ~${p.reply}</span></span><button class="ib" data-report="chat" aria-label="Report this chat" style="width:36px;height:36px">${ico("flag","#16201D",16)}</button><button class="btn g sm dk" style="height:36px" data-open="${p.id}">Profile</button><button class="ib nodk" data-open="${p.id}" aria-label="View profile">${ico("user","#16201D",20)}</button></div>
<div class="muted center" style="font-size:12px">Translated ${myLang()} ⇄ ${pl} automatically  ·  <button class="link" style="font-size:12px;color:var(--muted)" data-act="togOrig">${S.showOrig===false?"Show originals":"Hide originals"}</button></div>
<div class="col msgs" id="msgs" style="gap:10px">${msgs}</div>
<div style="height:12px" class="nodk"></div><div class="qr">${["What time works for you?","Can you bring the parts?","The door code is 2210","Thank you!"].map(t=>`<button class="chip" data-qr="${t}">${t}</button>`).join("")}</div><form data-form="msg" class="cta" style="gap:8px"><button type="button" class="ib" data-act="attach" aria-label="Attach photo">${ico("plus","#16201D",20)}</button><div class="in" style="flex:1;border-radius:22px;height:44px"><input name="msg" placeholder="Write in ${LNAME[myLang()]}…" autocomplete="off"></div><button class="ib" type="submit" style="background:var(--green);border:none" aria-label="Send">${ico("send","#fff",20)}</button></form></div></div><div class="dk">${nav("chats")}</div>`},

me:()=>{ensure();return `${topbar()}<div class="row" style="gap:14px"><span style="width:64px;height:64px;border-radius:32px;background:var(--ink);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-family:Sora,sans-serif;font-weight:700;font-size:22px">${(S.name||"S R").split(" ").map(x=>x[0]).join("").slice(0,2)}</span><span><h2 style="font-size:22px">${esc(S.name||"Sofia Ramírez")}</h2><span class="muted">${esc(S.email||"")}</span><span class="row wrap" style="gap:6px;margin-top:6px">${Object.entries(S.langs).map(lchip).join("")}</span></span></div>
<div class="card" style="padding:4px 16px">${[["globe","Language and translation",`App in ${LNAME[myLang()]}, chat translated`],["pin","Home",esc(S.address||"Not set")+(S.landlord?"  ·  Landlord: "+esc(S.llName||"not added"):"")],["lock","Payment methods","Visa ending 4421"],["shield","Verification","Email and phone confirmed"],["star","Saved providers",S.saved.length+" saved"],["user","Privacy and data","Download or delete your data"],["shield","Legal","Terms, privacy, cookies"]].map(([i,t,s])=>`<button class="row" style="gap:12px;padding:12px 0;border-bottom:1px solid #EDE8DF;width:100%;background:none;border-left:none;border-right:none;border-top:none;font:inherit;text-align:left" ${t==="Legal"?'data-legal="terms"':t==="Privacy and data"?'data-legal="privacy"':t==="Saved providers"?'data-go="saved"':'data-act="soon"'}><span class="eic" style="width:40px;height:40px;border-radius:12px">${ico(i,"#16201D",20)}</span><span style="flex:1"><b style="font-size:16px;font-weight:500">${t}</b><span class="muted" style="display:block">${s}</span></span><span style="display:inline-flex;transform:rotate(180deg)">${ico("back","#56605C",18)}</span></button>`).join("")}</div>
<div class="row between" style="font-size:15px"><span>Show originals under translations</span><button class="tog ${S.showOrig===false?"":"on"}" data-act="togOrig" role="switch" aria-checked="${S.showOrig!==false}"></button></div>
<button class="btn p" data-switch="provider">Switch to the provider app</button><button class="btn s" data-act="logout">Log out</button><p class="muted center">Kodu prototype  ·  v0.2</p>
<div style="height:12px"></div>${nav("me")}`}
});

/* provider replies, scripted for the prototype */
const REPLY=(p,j)=>({
  text:`Yes, ${j.day} ${j.slot} works. I can see the ${j.title.toLowerCase()} from your photos. Here is my quote.`,
  orig:{ET:`Jah, ${j.day} ${j.slot} sobib. Näen fotodelt ${j.title.toLowerCase()}. Siin on minu pakkumine.`,UK:`Так, ${j.day} ${j.slot} підходить. Бачу проблему на фото. Ось моя пропозиція.`,RU:`Да, ${j.day} ${j.slot} подходит. Вижу проблему на фото. Вот моё предложение.`,PT:`Sim, ${j.day} ${j.slot} dá. Vi o problema nas fotos. Aqui está o meu orçamento.`}[native(p)]||"…"
});
const CHITCHAT=[["Thanks, received. I will bring the parts.","Aitäh, sain kätte. Võtan osad kaasa."],["Could you send one more photo from the side?","Kas saadad veel ühe foto küljelt?"],["No problem, see you then.","Pole probleemi, kohtumiseni."]];
function openChat(pid){ensure();if(!S.chats[pid]){const p=find(pid);S.chats[pid]={pid,t:Date.now(),unread:0,msgs:[{sys:true,text:`Chat with ${p.name.split(" ")[0]} started · translated automatically`}]}}S.view=pid;save();go("chat")}
function providerReplies(pid){const c=S.chats[pid];const p=find(pid);const j=S.jobs2.find(x=>x.pid===pid&&x.status==="requested");c.typing=true;save();if(route==="chat"&&S.view===pid)render();
  setTimeout(()=>{c.typing=false;if(j){j.status="quoted";if(S.landlord&&S.llName){j.ll="pending";setTimeout(()=>{j.ll="approved";save();if(route==="job"||route==="chat")render();toast(esc(S.llName)+" approved the quote")},4000)}j.hours=1.5;j.materials=MAT[p.cat][1];j.matDesc=MAT[p.cat][0];const r=REPLY(p,j);c.msgs.push({text:r.text,orig:r.orig,when:"now"});c.msgs.push({quote:j.id,when:"now"})}else{const [t,o]=CHITCHAT[c.msgs.length%CHITCHAT.length];c.msgs.push({text:t,orig:o,when:"now"})}
    c.t=Date.now();if(!(route==="chat"&&S.view===pid))c.unread=(c.unread||0)+1;save();render();},1800)}

document.addEventListener("click",e=>{
  const t=e.target.closest("[data-nav],[data-open],[data-cat],[data-catf],[data-f],[data-fv],[data-fvn],[data-city],[data-langsel],[data-save],[data-book],[data-chat],[data-job],[data-day],[data-pick],[data-dphoto],[data-pay],[data-star],[data-rtag],[data-act]");if(!t)return;ensure();
  const d=t.dataset;
  if(d.nav){history=[];go(d.nav);return}
  if(d.open){S.view=d.open;S.recent=[d.open,...(S.recent||[]).filter(x=>x!==d.open)].slice(0,8);save();go("profile");return}
  if(d.cat!==undefined){S.cat=d.cat;S.q="";save();if(route==="search")render();else go("search");return}
  if(d.catf!==undefined){S.cat=d.catf;save();render();return}
  if(d.f!==undefined&&t.tagName!=="INPUT"){S.f[d.f]=!S.f[d.f];save();render();return}
  if(d.fv){S.f[d.fv]=d.val;save();render();return}
  if(d.fvn){S.f[d.fvn]=+d.val;save();render();return}
  if(d.city){S.f.city=d.city;S.f.area="";save();render();return}
  if(d.langsel!==undefined){if(d.langsel==="any"){S.f.lang=false;S.f.langSel=""}else{S.f.lang=true;S.f.langSel=d.langsel}save();render();return}
  if(d.save){S.saved=S.saved.includes(d.save)?S.saved.filter(x=>x!==d.save):[...S.saved,d.save];save();render();toast(S.saved.includes(d.save)?"Saved":"Removed from saved");return}
  if(d.book){S.view=d.book;S.draft=d.day?{day:d.day,slot:d.slot}:{};save();go("book");return}
  if(d.chat){openChat(d.chat);return}
  if(d.job){S.jobId=d.job;save();go("job");return}
  if(d.day&&route==="slots"){S.draft.day=d.day;S.draft.slot=null;save();render();return}
  if(d.pick){S.draft.slot=d.pick;S.draft.day=S.draft.day||Object.keys(find(S.view).slots)[0];save();render();return}
  if(d.dphoto){S.draft[d.dphoto]=true;save();render();toast("Photo added");return}
  if(d.pay){S.payMethod=d.pay;save();render();return}
  if(d.star){S.rv.stars=+d.star;save();render();return}
  if(d.rtag){S.rv.tags=S.rv.tags.includes(d.rtag)?S.rv.tags.filter(x=>x!==d.rtag):[...S.rv.tags,d.rtag];save();render();return}
  const a=d.act;
  if(a==="seeall"){S.cat="";S.q="";S.f.lang=true;save();go("search");return}
  if(a==="resetF"){S.f={lang:true,verified:true,avail:"This week",max:60,sort:"Best match",area:"",day:"",time:"",minR:0,lic:false,fast:false,city:"Tallinn",langSel:"",pricing:""};S.cat="";save();render();return}
  if(a==="share"){toast("Link copied: kodu.ee/p/"+S.view);return}
  if(a==="togOrig"){S.showOrig=S.showOrig===false?true:false;save();render();return}
  if(a==="attach"){toast("Photo attached");return}
  if(a==="sendRequest"){if(!S.draft.slot){err={slot:"Pick a time slot"};render();return}const p=find(S.view);const id="j"+Date.now();const j={id,pid:p.id,title:S.draft.title,desc:S.draft.desc,urgency:S.urgency||"This week",photos:["Photo 1","Photo 2"].filter(k=>S.draft[k]).length,day:S.draft.day,slot:S.draft.slot,status:"requested",hours:1.5,materials:0,matDesc:""};S.jobs2.push(j);S.jobId=id;if(!S.chats[p.id])openChat(p.id);const c=S.chats[p.id];c.msgs.push({me:true,text:`Hi ${p.name.split(" ")[0]}, ${j.title.toLowerCase()}. ${j.desc||""} Could you come ${j.day} at ${j.slot}?`,orig:`(${LNAME[myLang()]} original)`,when:"now"});c.t=Date.now();S.draft={};save();history=[];go("job");toast("Request sent and translated");providerReplies(p.id);return}
  if(a==="declineQuote"){const j=S.jobs2.find(x=>x.id===(d.jid||S.jobId));j.status="cancelled";save();render();toast("Quote declined");return}
  if(a==="payNow"){const j=S.jobs2.find(x=>x.id===S.jobId);j.status="paid";j.paidAt="today";save();go("paid");return}
  if(a==="confirmDone"){const j=S.jobs2.find(x=>x.id===S.jobId);j.status="done";save();render();toast(money(quote(j).total)+" released to "+find(j.pid).name.split(" ")[0]);return}
  if(a==="cancel"){const j=S.jobs2.find(x=>x.id===S.jobId);if(confirm(j.status==="paid"?"Cancel this booking? Cancelling within 24 h of the slot costs €15.":"Cancel this request?")){j.status="cancelled";save();render();toast("Cancelled")}return}
  if(a==="sendReview"){if(!S.rv.stars){toast("Pick a star rating","err");return}const j=S.jobs2.find(x=>x.id===S.jobId);j.rated=true;const ta=document.querySelector("textarea[name=rvtext]");if(ta)S.rv.text=ta.value;S.rv={stars:0,tags:[]};save();history=[];go("bookings");toast("Review sent, thank you");return}
});
document.addEventListener("submit",e=>{
  const f=e.target;const k=f.dataset.form;if(!["search","book","msg"].includes(k))return;e.preventDefault();ensure();
  if(k==="search"){S.q=f.q.value.trim();S.cat="";save();if(route!=="search")go("search");else render();return}
  if(k==="book"){S.draft.title=f.title.value.trim();S.draft.desc=f.desc.value.trim();if(!S.draft.title){err={title:"Say what needs doing"};render();return}save();go("slots");return}
  if(k==="msg"){const v=f.msg.value.trim();if(!v)return;const c=S.chats[S.view];c.msgs.push({me:true,text:v,orig:`(${LNAME[myLang()]} original)`,when:"now"});c.t=Date.now();save();render();providerReplies(S.view);return}
});
document.addEventListener("input",e=>{const i=e.target;if(i.dataset.range){ensure();S.f[i.dataset.range]=+i.value;save();const b=i.parentElement.querySelector("b");if(b)b.textContent="up to €"+i.value;const sb=document.querySelector("[data-go=back].btn");if(sb)sb.textContent="Show "+results().length+" providers"}});
document.addEventListener("change",e=>{const i=e.target;if(i.type==="checkbox"&&i.dataset.f){ensure();S.f[i.dataset.f]=i.checked;save();render()}if(i.dataset.chip==="urgency"){}});

if(S.loggedIn&&S.role!=="provider"){route="ehome";render()}

document.addEventListener("click",e=>{const t=e.target.closest("[data-hs]");if(!t)return;const sc=t.parentElement.querySelector(".hscroll");const step=Math.max(128,Math.floor(sc.clientWidth*0.8));sc.scrollBy({left:t.dataset.hs==="next"?step:-step,behavior:"smooth"})});
function syncArrows(){document.querySelectorAll(".hwrap").forEach(w=>{const sc=w.querySelector(".hscroll");w.classList.toggle("atstart",sc.scrollLeft<=2);w.classList.toggle("atend",sc.scrollLeft+sc.clientWidth>=sc.scrollWidth-2);w.classList.toggle("noscroll",sc.scrollWidth<=sc.clientWidth+2)})}
document.addEventListener("scroll",e=>{if(e.target.classList&&e.target.classList.contains("hscroll"))syncArrows()},true);
const _render=render;render=function(){_render();requestAnimationFrame(syncArrows)};
addEventListener("resize",syncArrows);

document.addEventListener("click",ev=>{const t=ev.target.closest("[data-dr],[data-dp],[data-resolve],[data-rebook],[data-report],[data-rp],[data-qr],[data-act=sendDispute],[data-act=sendReport],[data-cookie]");if(!t)return;ensure();const d=t.dataset;
  if(d.dr){S.dsp.r=d.dr;const ta=document.querySelector("textarea[name=dtext]");if(ta)S.dsp.t=ta.value;save();render();return}
  if(d.dp){S.dsp[d.dp]=true;const ta=document.querySelector("textarea[name=dtext]");if(ta)S.dsp.t=ta.value;save();render();toast("Photo added");return}
  if(d.act==="sendDispute"){if(!S.dsp.r){err={dr:"Choose what went wrong"};render();return}const j=S.jobs2.find(x=>x.id===S.jobId);j.status="disputed";j.dispute=S.dsp.r;S.dsp={};save();goBack();toast("Problem reported, payment on hold");return}
  if(d.resolve){const j=S.jobs2.find(x=>x.id===S.jobId);const tot=quote(j).total;if(d.resolve==="release"){j.status="done";toast("Payment released to the provider")}else{j.status=d.resolve==="full"?"refunded":"done";j.refund=d.resolve==="full"?tot:Math.round(tot*0.5*100)/100;toast(money(j.refund)+" refunded")}save();render();return}
  if(d.rebook){S.view=d.rebook;S.draft={};save();go("book");return}
  if(d.report){S.reportTarget={kind:d.report,name:d.report==="chat"?"this conversation":(find(S.view)||{}).name};S.rp="";save();go("report");return}
  if(d.rp){S.rp=d.rp;save();render();return}
  if(d.act==="sendReport"){S.rp="";save();goBack();toast("Report sent. We will review it and tell you the outcome");return}
  if(d.qr){const f=document.querySelector("form[data-form=msg],form[data-form=pmsg]");if(!f)return;f.msg.value=d.qr;f.requestSubmit();return}
});
